import{_ as l,l as o,o as e,c as n,v as t,p as h,x as r,d as s,i as E,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"TE / TM 对比","description":"","frontmatter":{"title":"TE / TM 对比","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/te-tm-polarization.md","filePath":"litho/te-tm-polarization.md","lastUpdated":1789023840000}'),p={name:"litho/te-tm-polarization.md"};function d(T,a,A,c,_,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="te-tm-对比" tabindex="-1">TE / TM 对比 <a class="header-anchor" href="#te-tm-对比" aria-label="Permalink to &quot;TE / TM 对比&quot;">​</a></h1><div class="epigraph"><p>矢量成像已经把 $|U|^2$ 换成能量沉积；还要问的是：同一对衍射级，电场平行于线还是躺在入射面里，条纹深度完全不同。</p><footer>—— 据 Flagello 高 NA 薄膜成像与 Yeung 矢量光刻模型对 s / p 干涉的讨论整理</footer></div><p><a href="/litho/vector-imaging">上一课</a>把高 \\(\\mathrm{NA}\\) 空中像升级为胶内能量沉积，并指出 TE（s）干涉深、TM（p）交叉项变弱。缺口是把这两偏振的<strong>成像差</strong>写成可对线栅使用的对比：同一节距、同一光瞳，只换偏振，NILS 差在哪。光瞳相位如何展开，留给<a href="/litho/zernike-aberrations">Zernike 像差</a>。产线 \\(k_1\\) 仍不在本课重写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课给出了矢量接口，但工艺上要选的是照明偏振：让密线走哪一个通道。约定相对线栅：TE 的电场平行于线条，两束电矢量近乎平行，干涉项 \\(\\mathbf{E}_1\\cdot\\mathbf{E}_2^*\\) 接近满额；TM 的电场在入射面内，随孔径角张开，夹角接近 \\(2\\theta\\) 时交叉项按余弦一类因子下降，暗区抬高，对比与 NILS 掉。缺口因此是这条对比差，而不是再推一遍「为什么标量不够」。</p><p>非偏振是两通道强度平均，密线得到中间值。要极值必须控偏振；只加大 \\(\\sigma\\) 填不满这笔账。</p><h3 id="对比差在最佳焦距就存在" tabindex="-1">对比差在最佳焦距就存在 <a class="header-anchor" href="#对比差在最佳焦距就存在" aria-label="Permalink to &quot;对比差在最佳焦距就存在&quot;">​</a></h3><p>离焦二次相位对两个通道都会乘，但 TM 损失在 \\(z=0\\) 已征收。把「浸没后焦深变差」全部写成 \\(k_2\\lambda/\\mathrm{NA}^2\\)，会把偏振税误记成轴向预算。Bossung 上，TM 主导的密线往往窗更瘦，即使光学焦深公式看起来只与 \\(\\mathrm{NA}\\) 有关。</p><p><span class="marginnote">线栅的 TE/TM 随取向转。水平密线与垂直密线要的「好偏振」正交。二维孔无法同时让两向都走纯 TE，这是接触孔比一维栅更早付矢量税的原因之一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把进入光瞳的每条光线分解为局部 s/p，在像面（或胶内）矢量叠加后再对源积分。Flagello 把高 NA 成像放进分层薄膜：界面上的 Fresnel 系数对 s/p 不同，驻波节点也不同。Yeung 的矢量核则把投影侧的偏振传递写进计算光刻。本课不推薄膜矩阵，只要求：报密线对比必须声明偏振；标量 \\(C\\) 是偏乐观的上界。</p><p>照明侧：线偏振、切向（azimuthal）偏振把能量推向 TE 通道，是浸没密线的常用附件。它不改 \\(\\mathrm{NA}/\\lambda\\) 截止，只改通带内两束的点积。</p><h3 id="浸没放大夹角" tabindex="-1">浸没放大夹角 <a class="header-anchor" href="#浸没放大夹角" aria-label="Permalink to &quot;浸没放大夹角&quot;">​</a></h3><p>\\(\\mathrm{NA}=n\\sin\\theta\\)。水把同样空间频率对应的 \\(\\theta\\) 做大，TM 退化来得更早。干式高 \\(\\mathrm{NA}\\) 已需小心；浸没必须默认矢量。本课不讲喷淋头，只钉夹角与点积。</p><p><span class="marginnote">「极化照明」几乎总是光源侧的偏振控制，不是把投影物镜改成偏振器。镀膜的 s/p 透过率差是二阶修正。</span></p>',15)),(e(),h(m,null,{default:r(()=>[E(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20VEC%5B%22%E7%9F%A2%E9%87%8F%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20TE%5B%22TE%3A%20%E7%94%B5%E7%9F%A2%E9%87%8F%E5%B9%B3%E8%A1%8C%22%5D%0A%20%20VEC%20--%3E%20TM%5B%22TM%3A%20%E5%85%A5%E5%B0%84%E9%9D%A2%E5%86%85%E5%BC%A0%E5%BC%80%22%5D%0A%20%20TE%20--%3E%20HI%5B%22%E5%B9%B2%E6%B6%89%E6%B7%B1%20%2F%20NILS%20%E9%AB%98%22%5D%0A%20%20TM%20--%3E%20LO%5B%22%E4%BA%A4%E5%8F%89%E9%A1%B9%E5%BC%B1%20%2F%20%E6%9A%97%E5%8C%BA%E6%8A%AC%E9%AB%98%22%5D%0A%20%20HI%20--%3E%20POL%5B%22%E7%85%A7%E6%98%8E%E5%81%8F%E6%8C%AF%E9%80%89%E6%8B%A9%22%5D%0A%20%20LO%20--%3E%20POL%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两束 TM 的电矢量随 \\(\\theta\\) 张开，相干叠加的调制相对 TE 下降；频率越靠近截止，\\(\\theta\\) 越大，密图形先死。这与离焦「高频先死」同构，只是本课的税在焦面就征收。掩模铬栅自身也会当弱偏振器，反射式吸收体还有取向差——那是掩模 3D 的缺口；本课的物是已经进光瞳的矢量场。</p><p>NILS 的定义不变，输入 \\(I\\) 换成能量沉积。上一课的 ILS 课仍然适用：TM 把阈值处的对数斜率削掉，剂量轴随之变脆。这就是为什么 SMO 目标里要写偏振，不能只优化标量 TCC。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到密线对比，高 \\(\\mathrm{NA}\\) 必须拆 TE/TM 或声明非偏振平均。Zernike 相位乘在每个偏振通道上，像差与矢量相乘，不互相替代。截止频率仍是 \\(\\mathrm{NA}/\\lambda\\)；矢量改的是同样进了瞳的两束还能黑多少。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是掩模 FDTD，也不是 EUV 多层膜偏振反射率表。不要引用未公开的机台偏振纯度指标。标量模型在低 \\(\\mathrm{NA}\\)、松节距上仍可用；切换判据是夹角与目标节距，不是品牌。切向偏振对孔类和正交密线有自己的代价，不是免费的「全部变 TE」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TE 电矢量平行于线，干涉深；TM 随 \\(\\theta\\) 张开，对比掉。</li><li>偏振税在最佳焦距已存在，与离焦叠加。</li><li>非偏振是平均；极值对比要控照明偏振。</li><li>取向正交的密线无法共用同一纯 TE。</li><li>像差在下一课进光瞳相位，与本课通道相乘。</li><li>出处：Flagello 等对高 NA 薄膜成像；Yeung 矢量光刻模型；Mack / Levinson 的产线表述。</li></ul>',9))])}const b=l(p,[["render",d]]);export{f as __pageData,b as default};
